// Ermittelt Modus (Liste offener Reviews / Detail-Review-Formular) und baut die passende Query.
// Gleiches Muster wie Trading-Entscheidungszentrale: Nav-Aufruf INLINE vor diesem Node (nicht
// parallel - vermeidet die dort gefundene n8n-Ausfuehrungsreihenfolge-Race), Trigger-Daten per
// Namens-Lookup. POST-Fallthrough referenziert den Code-Node VOR dem Postgres-Ausfuehren-Node,
// nie den Postgres-Node selbst (der ersetzt $json durch das rohe Query-Ergebnis).
let fromPost = null;
try { fromPost = $('POST: Review normalisieren + SQL bauen').first().json; } catch (e) { fromPost = null; }
const isFromPost = fromPost && fromPost.mode === 'detail_nach_post' && fromPost.trade_id !== undefined;

let tradeId;
if (isFromPost) {
  tradeId = fromPost.trade_id;
} else {
  const trigger = $('Webhook GET (Ansicht)').first().json;
  tradeId = (trigger.query && trigger.query.id) ? String(trigger.query.id) : null;
}

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }

let sql;
if (tradeId) {
  sql = `SELECT pt.trade_id, pt.ticker, pt.strategy, pt.direction, pt.status,
      pt.simulated_entry_price, pt.stop_price_initial, pt.target_price_initial, pt.exit_price,
      pt.exit_reason, pt.simulated_entry_time, pt.exit_time, pt.net_pnl, pt.gross_pnl,
      pt.realized_r_multiple, pt.holding_period_days, pt.maximum_favorable_excursion,
      pt.maximum_adverse_excursion, pt.theoretical_quantity, pt.risk_amount,
      pt.opportunity_score_at_entry, pt.risk_score_at_entry, pt.evidence_confidence_at_entry,
      r.entry_grund, r.trade_thesis,
      tr.vorschlag_sinnvoll, tr.entry_sinnvoll, tr.stop_sinnvoll, tr.target_sinnvoll,
      tr.hebel_sinnvoll, tr.richtung_richtig, tr.begruendung_korrekt, tr.kommentar, tr.reviewed_at
    FROM trading.paper_trades pt
    LEFT JOIN trading.recommendations r ON r.id = pt.recommendation_id
    LEFT JOIN trading.trade_reviews tr ON tr.trade_id = pt.trade_id
    WHERE pt.trade_id = ${pgStr(tradeId)};`;
} else {
  // Liste-Modus: EIN SELECT liefert genau eine Zeile mit drei JSON-Spalten (Vergleichs-Kennzahlen
  // System-vs-Nutzer + die eigentliche Liste offener Reviews) - vermeidet Mehrfach-Statements in
  // einem Postgres-Node (deren Rueckgabeverhalten bei mehreren Result-Sets uneinheitlich ist).
  sql = `SELECT
      (SELECT json_build_object(
         'anzahl', count(*),
         'avg_pnl', round(avg(net_pnl)::numeric, 2)
       ) FROM trading.paper_trades WHERE status = 'closed') AS system_stats,
      (SELECT json_build_object(
         'anzahl', count(*),
         'avg_pnl', round(avg(pt2.net_pnl)::numeric, 2)
       ) FROM trading.paper_trades pt2
        JOIN trading.recommendation_decisions rd
          ON rd.recommendation_id = pt2.recommendation_id AND rd.status = 'aktuell' AND rd.entscheidung = 'angenommen'
        WHERE pt2.status = 'closed') AS user_stats,
      (SELECT json_agg(row_to_json(t)) FROM (
         SELECT pt.trade_id, pt.ticker, pt.strategy, pt.direction, pt.exit_reason,
                pt.net_pnl, pt.realized_r_multiple, pt.simulated_entry_time, pt.exit_time
         FROM trading.paper_trades pt
         LEFT JOIN trading.trade_reviews tr ON tr.trade_id = pt.trade_id
         WHERE pt.status = 'closed' AND tr.id IS NULL
         ORDER BY pt.exit_time DESC
         LIMIT 20
       ) t) AS offene_liste;`;
}

return [{ json: { sql, mode: tradeId ? 'detail' : 'liste', trade_id: tradeId } }];

const rows = $input.all().map(i => i.json);
const ctx = $('Baue Query (Liste/Detail)').first().json;
let nav = {};
try { nav = $('Nav laden (GET)').first().json; } catch (e1) {
  try { nav = $('Nav laden (POST)').first().json; } catch (e2) { nav = {}; }
}

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function fmtNum(v, digits) { return (v === null || v === undefined) ? '-' : Number(v).toFixed(digits === undefined ? 2 : digits); }
function fmtDate(v) {
  if (!v) return '-';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
const RICHTUNG_LABEL = { long: 'LONG', short: 'SHORT' };
const URTEIL_BADGE = { ja: 'ok', teilweise: 'warn', nein: 'danger' };
const URTEIL_LABEL = { ja: 'Ja', teilweise: 'Teilweise', nein: 'Nein' };

const CSS = 'body{font-family:sans-serif;background:#0f1115;color:#e6e6e6;margin:0;padding:32px;max-width:1000px;margin:0 auto;}'
  + 'h1{font-size:22px;color:#fff;margin-bottom:4px;} h2{font-size:15px;color:#fff;margin-top:24px;margin-bottom:8px;}'
  + '.meta{color:#9aa0a6;font-size:13px;margin-bottom:16px;} .hint{color:#9aa0a6;font-size:12px;}'
  + '.card{background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:16px 20px;margin-bottom:14px;}'
  + '.card h3{margin:0 0 6px 0;font-size:16px;color:#fff;} .card a{color:#8ab4f8;text-decoration:none;}'
  + '.kpi-row{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0;}'
  + '.kpi{background:#1a1c20;padding:10px 16px;border-radius:6px;min-width:110px;}'
  + '.kpi .label{font-size:10px;color:#999;text-transform:uppercase;} .kpi .value{font-size:18px;color:#fff;margin-top:2px;}'
  + '.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;}'
  + '.badge.ok{background:#1c3a2a;color:#6bcf8e;} .badge.warn{background:#3a2c1c;color:#e0a854;}'
  + '.badge.danger{background:#3a1c1c;color:#e0665a;} .badge.muted{background:#22242a;color:#7a7d84;}'
  + 'button{background:#5b8def;border:none;color:#0f1115;font-weight:600;border-radius:6px;padding:8px 16px;font-size:13px;cursor:pointer;margin:4px 6px 4px 0;}'
  + 'button:hover{background:#7ba3f2;}'
  + 'select,textarea,input{background:#0f1115;border:1px solid #2a2d34;color:#e6e6e6;border-radius:6px;padding:6px 8px;font-size:13px;box-sizing:border-box;}'
  + 'textarea{width:100%;min-height:60px;margin-top:6px;}'
  + '.review-form{background:#1a1c20;border:1px solid #2a2d34;border-radius:6px;padding:14px;margin-top:10px;}'
  + '.review-form .feld{display:block;margin-bottom:10px;} .review-form label{display:block;font-size:12px;color:#9aa0a6;margin-bottom:3px;}';

const NAVBAR_LINKS = '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a></div>';

function pageWrap(title, body) {
  return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body>'
    + (nav && nav.navHtml ? nav.navHtml : NAVBAR_LINKS)
    + body
    + '</body></html>';
}

let html;

if (ctx.mode === 'liste') {
  const row = rows[0] || {};
  const systemStats = row.system_stats || { anzahl: 0, avg_pnl: null };
  const userStats = row.user_stats || { anzahl: 0, avg_pnl: null };
  const liste = Array.isArray(row.offene_liste) ? row.offene_liste : [];
  const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

  const vergleichHtml = '<h2>System- vs. Nutzer-Performance</h2>'
    + '<div class="kpi-row">'
    + '<div class="kpi"><div class="label">Alle Paper Trades</div><div class="value">' + esc(systemStats.anzahl) + ' Stück</div></div>'
    + '<div class="kpi"><div class="label">Ø PnL (alle)</div><div class="value">' + fmtNum(systemStats.avg_pnl) + ' EUR</div></div>'
    + '<div class="kpi"><div class="label">Davon von dir angenommen</div><div class="value">' + esc(userStats.anzahl) + ' Stück</div></div>'
    + '<div class="kpi"><div class="label">Ø PnL (angenommen)</div><div class="value">' + fmtNum(userStats.avg_pnl) + ' EUR</div></div>'
    + '</div>'
    + (userStats.anzahl < 5 ? '<div class="hint">Noch zu wenige eigene Entscheidungen für einen belastbaren Vergleich (Fallzahl unter 5).</div>' : '');

  if (liste.length === 0) {
    html = pageWrap('Paper-Trading-Review', ''
      + '<h1>Paper-Trading-Review</h1>'
      + '<div class="meta">Stand: ' + now + '</div>'
      + vergleichHtml
      + '<h2>Offene Reviews</h2>'
      + '<div class="card" style="text-align:center;padding:32px 20px;">'
      + '<h3>Keine offenen Reviews</h3>'
      + '<div class="hint">Alle geschlossenen Paper Trades sind bereits bewertet, oder es gibt noch keine geschlossenen Trades.</div>'
      + '</div>');
  } else {
    const cards = liste.map(t => {
      const richtungLabel = RICHTUNG_LABEL[t.direction] || esc(t.direction);
      const pnlKlass = (t.net_pnl || 0) >= 0 ? 'ok' : 'danger';
      return '<div class="card">'
        + '<h3><a href="/webhook/trade-review?id=' + esc(t.trade_id) + '">' + esc(t.ticker) + ' - ' + richtungLabel + '</a></h3>'
        + '<div class="hint">' + esc(t.strategy || '') + ' &middot; Exit-Grund: ' + esc(t.exit_reason || '-') + ' &middot; geschlossen: ' + fmtDate(t.exit_time) + '</div>'
        + '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">PnL</div><div class="value"><span class="badge ' + pnlKlass + '">' + fmtNum(t.net_pnl) + ' EUR</span></div></div>'
        + '<div class="kpi"><div class="label">R-Multiple</div><div class="value">' + fmtNum(t.realized_r_multiple) + '</div></div>'
        + '</div>'
        + '<a href="/webhook/trade-review?id=' + esc(t.trade_id) + '">Review ausfüllen &rarr;</a>'
        + '</div>';
    }).join('');
    html = pageWrap('Paper-Trading-Review', ''
      + '<h1>Paper-Trading-Review</h1>'
      + '<div class="meta">Stand: ' + now + ' &middot; ' + liste.length + ' offene Review(s)</div>'
      + vergleichHtml
      + '<h2>Offene Reviews</h2>'
      + cards);
  }
} else {
  const t = rows[0];
  if (!t || !t.trade_id) {
    html = pageWrap('Paper-Trading-Review', '<h1>Paper-Trading-Review</h1><div class="card">Trade nicht gefunden. <a href="/webhook/trade-review">Zurück zur Liste</a></div>');
  } else {
    const richtungLabel = RICHTUNG_LABEL[t.direction] || esc(t.direction);
    const pnlKlass = (t.net_pnl || 0) >= 0 ? 'ok' : 'danger';
    const bereitsBewertet = t.reviewed_at
      ? '<div class="card" style="border-color:#5b8def;"><strong>Bereits bewertet</strong> am ' + fmtDate(t.reviewed_at) + '. Erneutes Absenden überschreibt die bisherige Bewertung.</div>'
      : '';

    function urteilSelect(name, current) {
      const opts = [['', 'Bitte wählen'], ['ja', 'Ja'], ['teilweise', 'Teilweise'], ['nein', 'Nein']];
      return '<select name="' + name + '" form="form-review">' + opts.map(([v, l]) =>
        '<option value="' + v + '"' + (current === v ? ' selected' : '') + '>' + l + '</option>'
      ).join('') + '</select>';
    }

    const bisherigeUrteile = ['vorschlag_sinnvoll', 'entry_sinnvoll', 'stop_sinnvoll', 'target_sinnvoll', 'hebel_sinnvoll', 'richtung_richtig', 'begruendung_korrekt']
      .filter(k => t[k])
      .map(k => '<span class="badge ' + (URTEIL_BADGE[t[k]] || 'muted') + '">' + k + ': ' + (URTEIL_LABEL[t[k]] || t[k]) + '</span>')
      .join(' ');

    html = pageWrap(t.ticker + ' - Trade-Review', ''
      + '<a href="/webhook/trade-review" class="hint">&larr; Zurück zur Liste</a>'
      + '<h1>' + esc(t.ticker) + ' - ' + richtungLabel + '</h1>'
      + '<div class="meta">Strategie: ' + esc(t.strategy || '-') + ' &middot; Exit-Grund: ' + esc(t.exit_reason || '-') + '</div>'
      + bereitsBewertet
      + (t.reviewed_at ? '<div class="meta">Bisherige Urteile: ' + bisherigeUrteile + (t.kommentar ? '<div class="hint">"' + esc(t.kommentar) + '"</div>' : '') + '</div>' : '')

      + '<h2>Trade-Verlauf</h2>'
      + '<div class="kpi-row">'
      + '<div class="kpi"><div class="label">Einstieg</div><div class="value">' + fmtNum(t.simulated_entry_price) + '</div></div>'
      + '<div class="kpi"><div class="label">Stop (initial)</div><div class="value">' + fmtNum(t.stop_price_initial) + '</div></div>'
      + '<div class="kpi"><div class="label">Target (initial)</div><div class="value">' + fmtNum(t.target_price_initial) + '</div></div>'
      + '<div class="kpi"><div class="label">Exit-Kurs</div><div class="value">' + fmtNum(t.exit_price) + '</div></div>'
      + '<div class="kpi"><div class="label">Haltedauer</div><div class="value">' + (t.holding_period_days !== null && t.holding_period_days !== undefined ? t.holding_period_days + ' Tage' : '-') + '</div></div>'
      + '</div>'
      + '<div class="kpi-row">'
      + '<div class="kpi"><div class="label">PnL (netto)</div><div class="value"><span class="badge ' + pnlKlass + '">' + fmtNum(t.net_pnl) + ' EUR</span></div></div>'
      + '<div class="kpi"><div class="label">R-Multiple</div><div class="value">' + fmtNum(t.realized_r_multiple) + '</div></div>'
      + '<div class="kpi"><div class="label">MFE</div><div class="value">' + fmtNum(t.maximum_favorable_excursion) + '</div></div>'
      + '<div class="kpi"><div class="label">MAE</div><div class="value">' + fmtNum(t.maximum_adverse_excursion) + '</div></div>'
      + '</div>'
      + '<div class="meta">Einstieg: ' + fmtDate(t.simulated_entry_time) + ' &middot; Exit: ' + fmtDate(t.exit_time) + '</div>'
      + (t.trade_thesis ? '<div class="hint">These: ' + esc(t.trade_thesis) + '</div>' : '')
      + (t.entry_grund ? '<div class="hint">Entry-Begründung: ' + esc(t.entry_grund) + '</div>' : '')

      + '<h2>Review</h2>'
      + '<div class="review-form">'
      + '<form id="form-review" method="POST" action="/webhook/trade-review-abgeben">'
      + '<input type="hidden" name="trade_id" value="' + esc(t.trade_id) + '">'
      + '<div class="feld"><label>War der ursprüngliche Vorschlag insgesamt sinnvoll?</label>' + urteilSelect('vorschlag_sinnvoll', t.vorschlag_sinnvoll) + '</div>'
      + '<div class="feld"><label>Entry sinnvoll?</label>' + urteilSelect('entry_sinnvoll', t.entry_sinnvoll) + '</div>'
      + '<div class="feld"><label>Stop sinnvoll?</label>' + urteilSelect('stop_sinnvoll', t.stop_sinnvoll) + '</div>'
      + '<div class="feld"><label>Target sinnvoll?</label>' + urteilSelect('target_sinnvoll', t.target_sinnvoll) + '</div>'
      + '<div class="feld"><label>Hebel sinnvoll?</label>' + urteilSelect('hebel_sinnvoll', t.hebel_sinnvoll) + '</div>'
      + '<div class="feld"><label>Richtung (Long/Short) richtig?</label>' + urteilSelect('richtung_richtig', t.richtung_richtig) + '</div>'
      + '<div class="feld"><label>War die Begründung im Nachhinein korrekt?</label>' + urteilSelect('begruendung_korrekt', t.begruendung_korrekt) + '</div>'
      + '<textarea name="kommentar" placeholder="Kommentar (optional)" form="form-review">' + esc(t.kommentar || '') + '</textarea>'
      + '<div style="margin-top:8px;"><button type="submit" form="form-review">Review speichern</button></div>'
      + '</form>'
      + '<div class="hint">Dieses Urteil fließt nicht automatisch in Regeln ein - es wird gesammelt und erst nach Aggregation über mehrere Fälle als Lernvorschlag geprüft.</div>'
      + '</div>'
    );
  }
}

return [{ json: { html } }];

// $json ist hier "Nav laden (POST)" (Nav-Call INLINE vor diesem Node, gleiches Muster wie
// Trading-Entscheidungszentrale) - Trigger-Daten deshalb per Namens-Lookup statt aus $json.
const trigger = $('Webhook POST (Review)').first().json;
const j = trigger.body || trigger;

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }

const tradeId = j.trade_id ? String(j.trade_id).trim() : null;
const jaTeilweiseNein = new Set(['ja', 'teilweise', 'nein']);
function normUrteil(v) {
  const s = String(v || '').trim().toLowerCase();
  return jaTeilweiseNein.has(s) ? s : null;
}
const review = {
  vorschlag_sinnvoll: normUrteil(j.vorschlag_sinnvoll),
  entry_sinnvoll: normUrteil(j.entry_sinnvoll),
  stop_sinnvoll: normUrteil(j.stop_sinnvoll),
  target_sinnvoll: normUrteil(j.target_sinnvoll),
  hebel_sinnvoll: normUrteil(j.hebel_sinnvoll),
  richtung_richtig: normUrteil(j.richtung_richtig),
  begruendung_korrekt: normUrteil(j.begruendung_korrekt),
  kommentar: String(j.kommentar || '').trim(),
};

return {
  json: {
    trade_id: tradeId,
    review,
    // Nur pruefen, ob der Trade existiert und geschlossen ist - inhaltliche Werte werden nie aus
    // dem Body uebernommen (gleiches "nie dem Client vertrauen"-Muster wie
    // Trading-Entscheidungszentrale).
    load_sql: tradeId
      ? `SELECT trade_id, status FROM trading.paper_trades WHERE trade_id = ${pgStr(tradeId)};`
      : `SELECT NULL::text AS trade_id WHERE FALSE;`
  }
};

// Baut die UPSERT-SQL fuer trading.trade_reviews. Anders als bei Trading-Entscheidungszentrale
// braucht es hier kein optimistisches Locking und keinen system_werte_json-Snapshot: paper_trades
// ist nach status='closed' unveraendlich (eigene Audit-Historie), und ein Review darf jederzeit
// ueberschrieben werden (kein Verlauf pro Review noetig - eine Meinung des Nutzers pro Trade).
const loaded = $input.first().json; // Ergebnis von "DB: Trade laden (fuer Review)"
const ctx = $('POST: Baue Load-Query').first().json;
const { trade_id, review } = ctx;

function pgVal(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }

let sql;
let fehler = null;

if (!trade_id) {
  fehler = 'Keine trade_id uebermittelt.';
} else if (!loaded || !loaded.trade_id) {
  fehler = `Trade ${trade_id} existiert nicht.`;
} else if (loaded.status !== 'closed') {
  fehler = `Trade ${trade_id} ist noch nicht geschlossen (Status: ${loaded.status}) - Review erst nach Trade-Abschluss moeglich.`;
} else {
  sql = `INSERT INTO trading.trade_reviews
      (trade_id, vorschlag_sinnvoll, entry_sinnvoll, stop_sinnvoll, target_sinnvoll,
       hebel_sinnvoll, richtung_richtig, begruendung_korrekt, kommentar, reviewed_von, reviewed_at)
    VALUES
      (${pgVal(trade_id)}, ${pgVal(review.vorschlag_sinnvoll)}, ${pgVal(review.entry_sinnvoll)},
       ${pgVal(review.stop_sinnvoll)}, ${pgVal(review.target_sinnvoll)}, ${pgVal(review.hebel_sinnvoll)},
       ${pgVal(review.richtung_richtig)}, ${pgVal(review.begruendung_korrekt)}, ${pgVal(review.kommentar)},
       'oliver', now())
    ON CONFLICT (trade_id) DO UPDATE SET
      vorschlag_sinnvoll = EXCLUDED.vorschlag_sinnvoll,
      entry_sinnvoll = EXCLUDED.entry_sinnvoll,
      stop_sinnvoll = EXCLUDED.stop_sinnvoll,
      target_sinnvoll = EXCLUDED.target_sinnvoll,
      hebel_sinnvoll = EXCLUDED.hebel_sinnvoll,
      richtung_richtig = EXCLUDED.richtung_richtig,
      begruendung_korrekt = EXCLUDED.begruendung_korrekt,
      kommentar = EXCLUDED.kommentar,
      reviewed_von = EXCLUDED.reviewed_von,
      reviewed_at = now();`;
}

return [{
  json: {
    sql: sql || `SELECT 1;`,
    mode: 'detail_nach_post',
    trade_id,
    fehler,
  }
}];
